//! 🧪️ Four typed pixel intents retain original custody and match independent neutral semantic leaves.
use super::*;
use semio_framework_plugin::artifact_app_laws::OriginalWorkFixture;
use semio_s_artifact_raster_raster_model::{RasterLayerNode,RasterLayerMask,RasterTransform,RasterOwnedMap,RASTER_DOCUMENT_SCHEMA};
use semio_framework_value::ToValue;

fn loan()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128}}
fn snapshot()->RasterSnapshot{RasterSnapshot{schema:RASTER_DOCUMENT_SCHEMA.into(),id:"pixel-producer".into(),title:None,assets:RasterOwnedMap::new(),layers:vec![RasterLayerNode::Pixel{id:"paint".into(),name:"Paint".into(),visible:true,locked:false,opacity:1.0,blend_mode:"normal".into(),transform:RasterTransform::default(),width:Some(4),height:Some(3),image_key:None,mask:Some(RasterLayerMask{enabled:true,linked:true,invert:false,width:Some(4),height:Some(3),image_key:None,transform:RasterTransform::default()})}]}}
fn command(row:&serde_json::Value)->RasterCommand{let p=&row["payload"];let layer_id=p["layerId"].as_str().unwrap().into();match row["tool"].as_str().unwrap(){"fillRegion"=>RasterCommand::FillRegion(fill_region::FillRegion{layer_id,x:p["x"].as_f64().unwrap(),y:p["y"].as_f64().unwrap()}),"applyFilter"=>RasterCommand::ApplyFilter(apply_filter::ApplyFilter{layer_id,filter:p["filter"].as_str().unwrap().into(),amount:p["amount"].as_f64().unwrap()}),"transformImage"=>RasterCommand::TransformImage(transform_image::TransformImage{layer_id,operation:p["operation"].as_str().unwrap().into(),x:p["x"].as_u64().unwrap()as u32,y:p["y"].as_u64().unwrap()as u32,width:p["width"].as_u64().unwrap()as u32,height:p["height"].as_u64().unwrap()as u32,bilinear:p["bilinear"].as_bool().unwrap()}),"fillSelection"=>RasterCommand::FillSelection(fill_selection::FillSelection{layer_id}),_=>panic!("closed semantic pixel route")}}
fn numeric_json(value:&serde_json::Value)->serde_json::Value{match value{serde_json::Value::Number(value)=>serde_json::Value::Number(serde_json::Number::from_f64(value.as_f64().unwrap()).unwrap()),serde_json::Value::Array(values)=>serde_json::Value::Array(values.iter().map(numeric_json).collect()),serde_json::Value::Object(values)=>serde_json::Value::Object(values.iter().map(|(key,value)|(key.clone(),numeric_json(value))).collect()),_=>value.clone()}}
fn config(row:&serde_json::Value,caller:&mut OriginalWorkFixture)->RasterConfig{let mut config=RasterConfig{paint_target:row["target"].as_str().unwrap().into(),brush_color:"#ff0000".into(),brush_opacity:0.25,mask_value:128,fill_tolerance:32,..Default::default()};if let Some(rows)=row["selection"].as_array(){let rows=rows.iter().map(|row|semio_s_artifact_raster_raster_model::RasterSelectionSpan{start:row["start"].as_u64().unwrap()as u32,length:row["length"].as_u64().unwrap()as u32,coverage:row["coverage"].as_u64().unwrap()as u8}).collect::<Vec<_>>();let spans=caller.receive_native::<_,semio_s_artifact_raster_raster_model::RasterSelectionSpans>(rows,loan());config.pixel_selection=Some(crate::selection::RasterPixelSelection{layer_id:"paint".into(),target:config.paint_target.clone(),width:4,height:3,spans});}config}

#[test]
fn original_pixel_leaf_producer_matches_neutral_metadata_and_retires_every_prefix(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixtures.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){for cut in [None,Some(0),Some(1),Some(3),Some(7)]{
  let snapshot=snapshot();let mut caller=OriginalWorkFixture::new();let config=config(row,&mut caller);let mut command=command(row);let mut work=PixelLeafWork::new(row["tool"].as_str().unwrap());let mut received=false;let mut output=None;
  for turn in 0..10000{if cut==Some(turn){break}caller.work_turn(loan(),1024,|cx|{if !received{received=work.receive(&mut command,cx)?;}else if let Some(emit)=work.advance(&snapshot,&config,"pixel-producer-author",cx)?{output=Some(emit)}Ok(())}).unwrap();if output.is_some(){break}}
  let pending=output.is_none();
  if cut.is_none(){let mut emit=output.take().unwrap();assert_eq!(emit.artifact_mutations.len(),1);assert_eq!(emit.transaction.is_some(),row["tool"]=="fillRegion");let mutation=emit.artifact_mutations.pop().unwrap();let value=match &mutation{RasterMutation::FillRegion(value)=>value.to_value(),RasterMutation::ApplyFilter(value)=>value.to_value(),RasterMutation::TransformImage(value)=>value.to_value(),RasterMutation::FillSelection(value)=>value.to_value(),_=>panic!("exact semantic pixel leaf")};let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&value)).unwrap();assert_eq!(numeric_json(&actual),numeric_json(&row["expected"]));if let (Some(selected),RasterMutation::ApplyFilter(leaf))=(&config.pixel_selection,&mutation){if let Some(clip)=&leaf.selection{assert!(std::ptr::eq(clip.get(0).unwrap(),selected.spans.get(0).unwrap()));}}caller.retire_owned(mutation,loan());caller.retire_owned(std::mem::take(&mut emit.artifact_mutations),loan());if let Some(transaction)=emit.transaction.take(){caller.retire_owned(transaction,loan());}}
  if let Some(emit)=output.take(){caller.retire_owned(emit.artifact_mutations,loan());if let Some(transaction)=emit.transaction{caller.retire_owned(transaction,loan());}}
  if cut.is_some(){caller.cancel().cancel_now();if pending{caller.turn(loan(),|cx|{let before=cx.retained_progress();assert!(work.advance(&snapshot,&config,"pixel-producer-author",cx)?.is_none());assert_eq!(cx.retained_progress(),before);Ok(())}).unwrap();}}
  work.begin_close();for _ in 0..10000{if work.terminal_is_empty(){break}caller.turn(loan(),|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(32768)?;semio_framework_job::close_original_retained_step(cx,d,|grant|work.close_one(grant))?;Ok(())})).unwrap();}assert!(work.terminal_is_empty());caller.retire_owned(command,loan());caller.retire_owned(config,loan());caller.retire_owned(snapshot,loan());caller.finish();
 }}
}

#[test]
fn original_pixel_leaf_refusals_keep_every_owner_and_emit_no_mutation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixtures.json")).unwrap();
 for row in fixture["refusals"].as_array().unwrap(){let mut caller=OriginalWorkFixture::new();let mut snapshot=snapshot();if row["locked"]==true{let RasterLayerNode::Pixel{locked,..}=snapshot.layers.last_mut().unwrap()else{unreachable!()};*locked=true;}let config=config(row,&mut caller);let mut command=command(row);let mut work=PixelLeafWork::new(row["tool"].as_str().unwrap());let mut received=false;let mut failed=false;let mut failed_work=0;let mut output=None;
  for _ in 0..10000{let result=caller.work_turn(loan(),1024,|cx|{if !received{received=work.receive(&mut command,cx)?;}else{let before=cx.fuel_remaining();let turn=work.advance(&snapshot,&config,"pixel-producer-author",cx);if turn.is_err(){failed_work=before-cx.fuel_remaining();}output=turn?;}Ok(())});if result.is_err(){failed=true;break}if output.is_some(){break}}
  let emitted=output.is_some();if let Some(emit)=output.take(){caller.retire_owned(emit.artifact_mutations,loan());if let Some(transaction)=emit.transaction{caller.retire_owned(transaction,loan());}}work.begin_close();for _ in 0..10000{if work.terminal_is_empty(){break}caller.turn(loan(),|cx|cx.with_original_retirement(|cx|{let d=work.close_demands(32768)?;semio_framework_job::close_original_retained_step(cx,d,|grant|work.close_one(grant))?;Ok(())})).unwrap();}assert!(work.terminal_is_empty());caller.retire_owned((command,config,snapshot),loan());caller.finish();assert_eq!(!failed,row["accepted"].as_bool().unwrap());assert!(!emitted);assert_eq!(failed_work,1);
 }
}
